  _AccumulateNode(inputs: _AccumulateNodeInputs): _AccumulateNodeOutputs & { __id: OutputNodeId<_AccumulateNodeResult>; inputs: _AccumulateNodeInputPaths } {
    const id = this.addNode("_AccumulateNode", inputs);
    const inputPaths = {
      to_add: `${id}.inputs.to_add`,
      accumulation: `${id}.inputs.accumulation`,
    };
    return {
      ACCUMULATION: this.makeRef<"ACCUMULATION">(id, 0),
      __id: id as OutputNodeId<_AccumulateNodeResult>,
      inputs: inputPaths
    };
  }

